import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.ChTAMbUy.js";const s="/docs/assets/ai-gateway-overview.ZtX71jG_.png",n="/docs/assets/grant-workspace-access.B4Oyk5TH.png",i="/docs/assets/grant-workspace-access-agents-tab.DbFXF0Kc.png",w=JSON.parse('{"title":"External Models","description":"","frontmatter":{},"headers":[],"relativePath":"development/admin/external_models.md","filePath":"versions/development/admin/external_models.md","lastUpdated":1787837970000}'),l={name:"development/admin/external_models.md"};function d(c,e,p,g,h,m){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="external-models" tabindex="-1">External Models <a class="header-anchor" href="#external-models" aria-label="Permalink to &quot;External Models&quot;">​</a></h1><p>The <strong>AI Gateway</strong> admin page connects centrally managed model providers to prokube. Administrators can add provider credentials once, register models from those providers, and grant specific workspaces access to specific models.</p><p>Use this workflow when you need to:</p><ul><li>offer Mistral AI, Azure OpenAI, GitHub Models, or a custom OpenAI-compatible endpoint;</li><li>share a centrally managed provider credential without copying it into workspace Secrets;</li><li>control which workspaces can use each external model.</li></ul><p>For OpenAI, Anthropic, or Gemini, workspace users can instead create their own Model Configuration backed by a workspace Kubernetes Secret. See <a href="./../agentops/agents.html#_2-choose-or-create-a-model-configuration">Agents</a>.</p><p><img src="'+s+'" alt="AI Gateway page with provider catalog and platform-wide usage summary" loading="lazy"></p><h2 id="provider-options" tabindex="-1">Provider Options <a class="header-anchor" href="#provider-options" aria-label="Permalink to &quot;Provider Options&quot;">​</a></h2><p>The admin-managed provider catalog supports:</p><ul><li>Anthropic;</li><li>OpenAI;</li><li>Mistral AI;</li><li>Azure OpenAI;</li><li>GitHub Models;</li><li>custom OpenAI-compatible endpoints.</li></ul><p>Anthropic uses its native protocol. The other provider types use an OpenAI-compatible protocol. Custom and Azure OpenAI providers require an upstream host and path prefix.</p><h2 id="connect-a-provider" tabindex="-1">Connect a Provider <a class="header-anchor" href="#connect-a-provider" aria-label="Permalink to &quot;Connect a Provider&quot;">​</a></h2><p>Open <strong>AI Gateway</strong> under <strong>Admin</strong>, then select <strong>Add Provider</strong>. Configure:</p><ul><li><strong>Provider</strong>: select an entry from the provider catalog.</li><li><strong>Provider name</strong>: unique name for the provider connection.</li><li><strong>Provider API key</strong>: credential stored centrally by prokube.</li><li><strong>Upstream host</strong> and <strong>Path prefix</strong>: required for custom and Azure OpenAI providers.</li><li><strong>Models</strong>: optional comma- or newline-separated model IDs to add immediately.</li></ul><p>Provider API keys are write-only. To rotate one later, edit the provider and enter a <strong>Replacement API key</strong>.</p><h2 id="add-models" tabindex="-1">Add Models <a class="header-anchor" href="#add-models" aria-label="Permalink to &quot;Add Models&quot;">​</a></h2><p>Open a provider and switch to its <strong>Models</strong> tab. Models can be added in two ways:</p><ul><li><strong>Discover models</strong> queries the provider and lets you select one or more returned model IDs.</li><li><strong>Add manually</strong> registers a model ID directly.</li></ul><p>The main <strong>Models</strong> table shows each model&#39;s provider, API protocol, workspace-access count, and base URL. A model cannot be deleted while a workspace grant still references it. Revoke those grants first.</p><h2 id="grant-workspace-access" tabindex="-1">Grant Workspace Access <a class="header-anchor" href="#grant-workspace-access" aria-label="Permalink to &quot;Grant Workspace Access&quot;">​</a></h2><p>Select <strong>Grant Workspace Access</strong>, then choose:</p><ul><li><strong>Workspace</strong>: the workspace that should receive the model.</li><li><strong>Route ID / ModelConfig name</strong>: the name shown in that workspace&#39;s Model Configurations.</li><li><strong>Resource</strong>: the provider model to grant.</li></ul><p>The grant creates a Model Configuration in the target workspace. It appears automatically on the workspace&#39;s <strong>Agents</strong> page, tagged <strong>AI Gateway</strong> as its origin. Users can select it when creating an agent without creating their own provider Secret.</p><p><img src="'+n+'" alt="Workspace Access table with an external model grant" loading="lazy"></p><p><img src="'+i+'" alt="Granted external model shown as an AI Gateway Model Configuration" loading="lazy"></p><p>The central provider credential is not exposed to the workspace. Revoke the grant from <strong>Workspace Access</strong> when the workspace should no longer use the model.</p><p>An admin-granted model is consumed by kagent agents through its generated Model Configuration. It is not selectable as a workload when creating a user API key on the <strong>API Keys</strong> page.</p><h2 id="usage-and-cost" tabindex="-1">Usage and Cost <a class="header-anchor" href="#usage-and-cost" aria-label="Permalink to &quot;Usage and Cost&quot;">​</a></h2><p>The <strong>Usage and Cost</strong> panel shows authenticated Agent Gateway traffic across all workspaces. Select Last hour, Last 24 hours, Last 7 days, or Last 30 days to view:</p><ul><li>total, successful, and failed requests;</li><li>request trends;</li><li>LLM input and output tokens;</li><li>estimated LLM cost.</li></ul><p>These figures are observability estimates, not billing records. Use the workspace <a href="./../platform/api_keys.html#usage-dashboard">API Key Usage Dashboard</a> to inspect usage attributed to visible keys in one workspace.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./../agentops/agents.html">Agents</a></li><li><a href="./../agentops/agent_gateway.html">Agent Gateway</a></li><li><a href="./../platform/api_keys.html">API Keys</a></li><li><a href="./../agentops/llm_serving.html">LLM Serving</a></li></ul>',32)])])}const k=a(l,[["render",d]]);export{w as __pageData,k as default};
